 "testability": {
  "p_testable": 0.8,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior work was found that directly addresses whether opponent next-possession PPP or own-sequence lags drive AVOID labels for play types."
 },
